using System.Text.Json;
namespace SimplePZMapmaker.Core;
/// <summary>Replays bounded, reversible terrain strokes without overwriting manual terrain, occupied tiles, or divergent proxy sprites.</summary>
public static class LinearFeatureEditor {
 public const int MaximumFeatures=64,MaximumPoints=512,MaximumCells=100000;
 public static readonly string[] Kinds=["road","river","railway","sidewalk","bridge"];
 static T Copy<T>(T value)=>JsonSerializer.Deserialize<T>(JsonSerializer.Serialize(value))!;
 public static void Validate(MapProject p){
  if(p.Terrain is null)throw new ArgumentException("Invalid terrain layer.");
  if(p.LinearFeatures is null||p.LinearFeatures.Count>MaximumFeatures||p.LinearFeatures.Any(f=>f is null)||p.LinearFeatures.Select(f=>f.Id).Distinct().Count()!=p.LinearFeatures.Count)throw new ArgumentException("At most 64 uniquely identified linear features are supported.");
  if(p.LinearFeatures.SelectMany(f=>f.DecorationIds??[]).Distinct().Count()!=p.LinearFeatures.Sum(f=>f.DecorationIds?.Count??0))throw new ArgumentException("Linear feature artwork IDs overlap.");
  long total=0;foreach(var f in p.LinearFeatures){ValidateFeature(f);total+=f.Underlay.Count;if(total>MaximumCells)throw new ArgumentException("Linear features cover more than 100,000 managed tiles.");var indices=new HashSet<int>();foreach(var c in f.Underlay){if(c.Index<0||c.Index>=p.Terrain.Length||!indices.Add(c.Index)||!Enum.IsDefined(c.Terrain)||!Enum.IsDefined(c.RenderedTerrain)||c.Surface is not null&&!VisualStyles.TileId(c.Surface)||c.RenderedSurface is not null&&!VisualStyles.TileId(c.RenderedSurface))throw new ArgumentException("Invalid linear feature underlay.");}
   if(f.DecorationIds.Count>4096||f.GeneratedDecorations.Count!=f.DecorationIds.Count||f.GeneratedDecorations.Where((d,i)=>d is null||d.Id!=f.DecorationIds[i]||d.X<0||d.Y<0||d.X>=p.Width||d.Y>=p.Height||d.Parts is null||d.Parts.Count!=1||d.Parts[0].Dx!=0||d.Parts[0].Dy!=0||d.Asset!=d.Parts[0].Tile||!RailTiles.Contains(d.Asset)).Any()||f.DecorationIds.Distinct().Count()!=f.DecorationIds.Count)throw new ArgumentException("Invalid generated railway artwork.");
  }
 }
 static readonly HashSet<string> RailTiles=["industry_railroad_01_0","industry_railroad_01_2","industry_railroad_01_3","industry_railroad_01_5"];
 public static void ValidateFeature(LinearFeature f){
  if(f is null||string.IsNullOrWhiteSpace(f.Id)||f.Id.Length>72||!Kinds.Contains(f.Kind)||!double.IsFinite(f.Width)||f.Width is <1 or >64||f.Interpolation is not("polyline" or "catmull-rom")||f.Points is null||f.Points.Count is <2 or >MaximumPoints||f.Points.Any(p=>p is null||!double.IsFinite(p.X)||!double.IsFinite(p.Y)||Math.Abs(p.X)>100000||Math.Abs(p.Y)>100000)||f.Points.Zip(f.Points.Skip(1)).All(v=>v.First==v.Second)||f.SourcePath is null||f.SourcePath.Count>512||f.SourcePath.Any(p=>p is null||!double.IsFinite(p.Longitude)||!double.IsFinite(p.Latitude)||p.Longitude is < -180 or >180||p.Latitude is < -85 or >85)||f.SourceId?.Length>100||f.SourceTags is null||f.SourceTags.Count>48||f.SourceTags.Any(v=>v.Key.Length>100||v.Value is null||v.Value.Length>300)||f.Underlay is null||f.DecorationIds is null||f.GeneratedDecorations is null||f.AssetSources is null||f.AssetSources.Count>4||f.AssetSources.Any(v=>!RailTiles.Contains(v.Key)||v.Value!="game"))throw new ArgumentException("Invalid linear feature: choose a kind, 2–512 finite points, and a width of 1–64 tiles.");
  if(f.Kind=="railway"&&(f.Interpolation!="polyline"||f.Points.Zip(f.Points.Skip(1)).Any(v=>Math.Abs(v.First.X-v.Second.X)>.001&&Math.Abs(v.First.Y-v.Second.Y)>.001)))throw new ArgumentException("Railway artwork supports straight cardinal segments. Add an orthogonal node instead of a diagonal or curved segment.");
 }
 public static MapProject Put(MapProject project,LinearFeature feature){Validate(project);ValidateFeature(feature);var list=Copy(project.LinearFeatures);var next=Copy(feature);next.Underlay=[];next.DecorationIds=[];next.GeneratedDecorations=[];var old=list.FindIndex(f=>f.Id==next.Id);if(old<0){if(list.Count>=MaximumFeatures)throw new ArgumentException("The map already has 64 editable linear features.");list.Add(next);}else list[old]=next;return Rebuild(project,list);}
 public static MapProject Remove(MapProject project,string id){Validate(project);if(!project.LinearFeatures.Any(f=>f.Id==id))throw new ArgumentException("The linear feature no longer exists.");return Rebuild(project,Copy(project.LinearFeatures.Where(f=>f.Id!=id).ToList()));}
 public static MapProject Rebuild(MapProject project,List<LinearFeature> features){
  // All work happens on a draft. Every work/placement/resource budget is checked before returning it.
  var p=Copy(project);var mask=TerrainEditMask.Decode(p);var protectedCells=new HashSet<int>();var oldOwned=project.LinearFeatures.SelectMany(f=>f.GeneratedDecorations).ToDictionary(d=>d.Id);
  foreach(var d in p.Decorations.ToArray())if(oldOwned.TryGetValue(d.Id,out var original)){if(JsonSerializer.Serialize(d)==JsonSerializer.Serialize(original))p.Decorations.Remove(d);else foreach(var part in d.Parts)protectedCells.Add((d.Y+part.Dy)*p.Width+d.X+part.Dx);}
  foreach(var b in p.Buildings)foreach(var i in BuildingDesigner.Occupied(b,false)){var x=b.X+i%(b.Width+1);var y=b.Y+i/(b.Width+1);if(x>=0&&y>=0&&x<p.Width&&y<p.Height)protectedCells.Add(y*p.Width+x);}
  foreach(var m in p.StaticModels)foreach(var cell in StaticModelPlacement.FootprintCells(m))protectedCells.Add((m.Y+cell.Dy)*p.Width+m.X+cell.Dx);foreach(var s in p.Spawns)protectedCells.Add(s.Y*p.Width+s.X);foreach(var d in p.Decorations)foreach(var part in d.Parts)protectedCells.Add((d.Y+part.Dy)*p.Width+d.X+part.Dx);
  foreach(var f in project.LinearFeatures.AsEnumerable().Reverse())foreach(var c in f.Underlay){var matches=p.Terrain[c.Index]==c.RenderedTerrain&&p.SurfaceTiles.GetValueOrDefault(c.Index)==c.RenderedSurface&&TerrainEditMask.IsEdited(mask,c.Index)==c.RenderedEdited;if(!matches){protectedCells.Add(c.Index);continue;}if(protectedCells.Contains(c.Index))continue;p.Terrain[c.Index]=c.Terrain;if(c.Surface is null)p.SurfaceTiles.Remove(c.Index);else p.SurfaceTiles[c.Index]=c.Surface;SetEdited(mask,c.Index,c.Edited);}
  p.LinearFeatures=[];var total=0;foreach(var f in features){ValidateFeature(f);f.Underlay=[];f.DecorationIds=[];f.GeneratedDecorations=[];var cells=Rasterize(f,p.Width,p.Height);total+=cells.Count;if(total>MaximumCells)throw new ArgumentException("Linear features exceed the 100,000-tile budget. Reduce their width, length, or count.");var rendered=f.Kind switch{"river"=>Terrain.Water,"sidewalk"=>Terrain.Pavement,"railway"=>Terrain.Dirt,_=>Terrain.Road};
   foreach(var i in cells){if(protectedCells.Contains(i)||TerrainEditMask.IsEdited(mask,i))continue;var before=p.Terrain[i];if(f.Kind is "road" or "sidewalk" or "railway"&&before==Terrain.Water)continue;if(f.Kind=="river"&&before is Terrain.Road or Terrain.Pavement)continue;if(f.Kind=="sidewalk"&&before==Terrain.Road)continue;var surface=p.SurfaceTiles.GetValueOrDefault(i);if(surface is not null)continue;f.Underlay.Add(new(i,before,surface,false,rendered,null,false));p.Terrain[i]=rendered;}
   if(f.Kind=="railway")AddRails(p,f,protectedCells,mask);p.LinearFeatures.Add(f);
  }
  p.TerrainEdits=TerrainEditMask.Encode(mask);p.Version=Math.Max(9,p.Version);Validate(p);return p;
 }
 static void SetEdited(byte[] mask,int i,bool value){if(value)mask[i/8]|=(byte)(1<<(i%8));else mask[i/8]&=(byte)~(1<<(i%8));}
 static void AddRails(MapProject p,LinearFeature f,HashSet<int> blocked,byte[] mask){
  f.AssetSources=[];var placed=new HashSet<int>();for(var segment=1;segment<f.Points.Count;segment++){var a=f.Points[segment-1];var b=f.Points[segment];var horizontal=Math.Abs(b.X-a.X)>=Math.Abs(b.Y-a.Y);var min=(int)Math.Max(0,Math.Floor(horizontal?Math.Min(a.X,b.X):Math.Min(a.Y,b.Y)));var max=(int)Math.Min((horizontal?p.Width:p.Height)-1,Math.Ceiling(horizontal?Math.Max(a.X,b.X):Math.Max(a.Y,b.Y)));var axis=(int)Math.Round(horizontal?a.Y:a.X);for(var at=min;at<=max;at++)for(var side=0;side<2;side++){var x=horizontal?at:axis+side;var y=horizontal?axis+side:at;if(x<0||y<0||x>=p.Width||y>=p.Height)continue;var i=y*p.Width+x;if(blocked.Contains(i)||TerrainEditMask.IsEdited(mask,i)||p.Terrain[i]==Terrain.Water||p.SurfaceTiles.ContainsKey(i)||!placed.Add(i))continue;if(f.GeneratedDecorations.Count>=4096||p.Decorations.Count>=10000)throw new ArgumentException("Railway artwork exceeds the decoration budget. Shorten the railway or split the map into sections.");var tile=$"industry_railroad_01_{(horizontal?(side==0?3:5):(side==0?0:2))}";if(p.AssetSources.TryGetValue(tile,out var source)&&source!="game")throw new ArgumentException("A railway resource is overridden by a mod. Choose the original game provider before placing railway artwork.");var d=new WorldDecoration{Id=$"linear-{f.Id}-{i}",X=x,Y=y,Asset=tile,Parts=[new(0,0,tile)]};f.GeneratedDecorations.Add(Copy(d));f.DecorationIds.Add(d.Id);f.AssetSources[tile]="game";p.AssetSources[tile]="game";p.Decorations.Add(d);}}
 }
 public static List<LinearPoint> Sample(LinearFeature f){ValidateFeature(f);if(f.Interpolation=="polyline")return [..f.Points];var result=new List<LinearPoint>();for(var i=0;i<f.Points.Count-1;i++){var p0=f.Points[Math.Max(0,i-1)];var p1=f.Points[i];var p2=f.Points[i+1];var p3=f.Points[Math.Min(f.Points.Count-1,i+2)];var length=Math.Abs(p2.X-p1.X)+Math.Abs(p2.Y-p1.Y);var steps=(int)Math.Clamp(Math.Ceiling(length/2),8,256);for(var j=0;j<steps;j++){var t=j/(double)steps;var t2=t*t;var t3=t2*t;double Axis(double a,double b,double c,double d)=>.5*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t2+(-a+3*b-3*c+d)*t3);result.Add(new(Axis(p0.X,p1.X,p2.X,p3.X),Axis(p0.Y,p1.Y,p2.Y,p3.Y)));if(result.Count>16384)throw new ArgumentException("The curve exceeds the sampling budget. Use fewer nodes or polyline interpolation.");}}result.Add(f.Points[^1]);return result;}
 public static HashSet<int> Rasterize(LinearFeature f,int width,int height){var points=Sample(f);var result=new HashSet<int>();var radius=f.Width/2;long work=0;for(var i=1;i<points.Count;i++){var a=points[i-1];var b=points[i];var dx=b.X-a.X;var dy=b.Y-a.Y;var enter=0d;var exit=1d;bool Clip(double direction,double distance){if(direction==0)return distance>=0;var t=distance/direction;if(direction<0){if(t>exit)return false;enter=Math.Max(enter,t);}else{if(t<enter)return false;exit=Math.Min(exit,t);}return true;}
  if(!Clip(-dx,a.X+radius)||!Clip(dx,width+radius-a.X)||!Clip(-dy,a.Y+radius)||!Clip(dy,height+radius-a.Y))continue;var x0=a.X+enter*dx;var y0=a.Y+enter*dy;var x1=a.X+exit*dx;var y1=a.Y+exit*dy;var steps=(int)Math.Ceiling(Math.Max(Math.Abs(x1-x0),Math.Abs(y1-y0))*2);for(var step=0;step<=steps;step++){var t=steps==0?0:step/(double)steps;var x=x0+(x1-x0)*t;var y=y0+(y1-y0)*t;var left=Math.Max(0,(int)Math.Floor(x-radius));var right=Math.Min(width-1,(int)Math.Ceiling(x+radius));var top=Math.Max(0,(int)Math.Floor(y-radius));var bottom=Math.Min(height-1,(int)Math.Ceiling(y+radius));work+=(long)(right-left+1)*(bottom-top+1);if(work>5_000_000)throw new ArgumentException("The linear stroke exceeds the work budget. Reduce its width or node count.");for(var yy=top;yy<=bottom;yy++)for(var xx=left;xx<=right;xx++)if(Math.Pow(xx+.5-x,2)+Math.Pow(yy+.5-y,2)<=radius*radius){result.Add(yy*width+xx);if(result.Count>MaximumCells)throw new ArgumentException("The stroke covers more than 100,000 tiles.");}}}return result;}
}
